{
  "summary": "The ENOSPC errors on kafka-02 are caused by the root filesystem filling up, primarily due to unbounded systemd journal logs in /var/log/journal.",
  "likely_cause": "Unbounded journald logs consuming /var space",
  "confidence": "high",
  "claims": [
    {
      "text": "The root filesystem was completely full and /var/log/journal was the largest directory.",
      "evidence_ids": ["INC-0089#2"],
      "quote": "the root filesystem completely full... /var/log/journal, which was by far the largest"
    },
    {
      "text": "Running journalctl --vacuum-size=500M freed space and stopped ENOSPC errors.",
      "evidence_ids": ["INC-0089#3"],
      "quote": "sudo journalctl --vacuum-size=500M on kafka-01. The root disk dropped back to a comfortable level"
    },
    {
      "text": "Runbook RB-008 recommends checking /var/log/journal and limiting its size with SystemMaxUse.",
      "evidence_ids": ["RB-008#0"],
      "quote": "/var/log/journal is the biggest ... Make it stick with SystemMaxUse=500M"
    }
  ],
  "next_checks": [
    "Verify that SystemMaxUse is configured and active on all Kafka hosts.",
    "Monitor /var/log/journal size regularly with journalctl --disk-usage.",
    "Check for other large directories under /var that could fill the root disk."
  ]
}
